SELECT a.application_id, a.application_no, a.status_code, a.current_owner_user, CASE WHEN a.primary_person_id IS NOT NULL THEN 'Y' ELSE 'N' END applicant_ready, CASE WHEN EXISTS ( SELECT 1 FROM mff_application_parties ap JOIN mff_income_sources i ON i.application_party_id=ap.application_party_id WHERE ap.application_id=a.application_id AND NVL(i.verified_flag,'N')='Y') THEN 'Y' ELSE 'N' END income_ready, CASE WHEN EXISTS ( SELECT 1 FROM mff_application_property x WHERE x.application_id=a.application_id AND x.selected_flag='Y') THEN 'Y' ELSE 'N' END property_ready, (SELECT COUNT(*) FROM mff_application_documents d WHERE d.application_id=a.application_id) document_count, (SELECT COUNT(*) FROM mff_application_documents d WHERE d.application_id=a.application_id AND NVL(d.verification_status,'PENDING')='PENDING') document_pending_count, (SELECT COUNT(*) FROM mff_application_documents d WHERE d.application_id=a.application_id AND d.verification_status='REJECTED') document_rejected_count, (SELECT COUNT(*) FROM mff_vw_missing_documents md WHERE md.application_id=a.application_id) missing_required_document_count, CASE WHEN EXISTS ( SELECT 1 FROM mff_credit_inquiries q WHERE q.application_id=a.application_id AND q.result_code='PASS') THEN 'Y' ELSE 'N' END credit_inquiry_ready, CASE WHEN EXISTS (SELECT 1 FROM mff_credit_studies s WHERE s.application_id=a.application_id) THEN 'Y' ELSE 'N' END credit_study_ready, CASE WHEN EXISTS ( SELECT 1 FROM mff_credit_decisions c WHERE c.application_id=a.application_id AND c.decision_code IN ('APPROVE','CONDITIONAL')) THEN 'Y' ELSE 'N' END credit_decision_ready, CASE WHEN EXISTS ( SELECT 1 FROM mff_calculation_runs c WHERE c.application_id=a.application_id AND NVL(c.calc_status,'COMPLETE')='COMPLETE') THEN 'Y' ELSE 'N' END calculation_ready, CASE WHEN EXISTS ( SELECT 1 FROM mff_subsidy_approvals s WHERE s.application_id=a.application_id AND s.approval_status='APPROVED') THEN 'Y' ELSE 'N' END subsidy_ready, CASE WHEN EXISTS ( SELECT 1 FROM mff_finance_offers o WHERE o.application_id=a.application_id AND o.offer_status IN ('ISSUED','ACCEPTED')) THEN 'Y' ELSE 'N' END offer_ready, CASE WHEN EXISTS ( SELECT 1 FROM mff_contracts c WHERE c.application_id=a.application_id AND (c.signed_flag='Y' OR c.contract_status='SIGNED')) THEN 'Y' ELSE 'N' END contract_ready, CASE WHEN EXISTS (SELECT 1 FROM mff_loans l WHERE l.application_id=a.application_id) THEN 'Y' ELSE 'N' END loan_ready, (SELECT COUNT(*) FROM mff_work_assignments w WHERE w.application_id=a.application_id AND NVL(w.assignment_status,'OPEN')<>'COMPLETED') open_tasks, (SELECT COUNT(*) FROM mff_work_assignments w WHERE w.application_id=a.application_id AND NVL(w.assignment_status,'OPEN')<>'COMPLETED' AND w.due_date<TRUNC(SYSDATE)) overdue_tasks, ROUND(100 * ( CASE WHEN a.primary_person_id IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN EXISTS (SELECT 1 FROM mff_application_parties ap JOIN mff_income_sources i ON i.application_party_id=ap.application_party_id WHERE ap.application_id=a.application_id AND NVL(i.verified_flag,'N')='Y') THEN 1 ELSE 0 END + CASE WHEN EXISTS (SELECT 1 FROM mff_application_property x WHERE x.application_id=a.application_id AND x.selected_flag='Y') THEN 1 ELSE 0 END + CASE WHEN EXISTS (SELECT 1 FROM mff_application_documents d WHERE d.application_id=a.application_id) AND NOT EXISTS (SELECT 1 FROM mff_vw_missing_documents md WHERE md.application_id=a.application_id) AND NOT EXISTS (SELECT 1 FROM mff_application_documents d WHERE d.application_id=a.application_id AND d.verification_status='REJECTED') THEN 1 ELSE 0 END + CASE WHEN EXISTS (SELECT 1 FROM mff_credit_inquiries q WHERE q.application_id=a.application_id AND q.result_code='PASS') THEN 1 ELSE 0 END + CASE WHEN EXISTS (SELECT 1 FROM mff_credit_studies s WHERE s.application_id=a.application_id) THEN 1 ELSE 0 END + CASE WHEN EXISTS (SELECT 1 FROM mff_credit_decisions c WHERE c.application_id=a.application_id AND c.decision_code IN ('APPROVE','CONDITIONAL')) THEN 1 ELSE 0 END + CASE WHEN EXISTS (SELECT 1 FROM mff_calculation_runs c WHERE c.application_id=a.application_id AND NVL(c.calc_status,'COMPLETE')='COMPLETE') THEN 1 ELSE 0 END + CASE WHEN EXISTS (SELECT 1 FROM mff_subsidy_approvals s WHERE s.application_id=a.application_id AND s.approval_status='APPROVED') THEN 1 ELSE 0 END + CASE WHEN EXISTS (SELECT 1 FROM mff_finance_offers o WHERE o.application_id=a.application_id AND o.offer_status IN ('ISSUED','ACCEPTED')) THEN 1 ELSE 0 END + CASE WHEN EXISTS (SELECT 1 FROM mff_contracts c WHERE c.application_id=a.application_id AND (c.signed_flag='Y' OR c.contract_status='SIGNED')) THEN 1 ELSE 0 END + CASE WHEN EXISTS (SELECT 1 FROM mff_loans l WHERE l.application_id=a.application_id) THEN 1 ELSE 0 END ) / 12, 0) readiness_pct FROM mff_applications a;
